import { Order } from '../../domain/entities/Order';
import { OrderRepository } from '../../domain/repositories/OrderRepository';
import { ProductRepository } from '../../domain/repositories/ProductRepository';
import { StockManager } from '../../domain/services/StockManager';
import { CreateOrderRequest, OrderDto } from '../dtos/OrderDto';

export class PlaceOrderUseCase {
  constructor(
    private orderRepository: OrderRepository,
    private productRepository: ProductRepository,
    private stockManager: StockManager
  ) {}

  execute(request: CreateOrderRequest): OrderDto {
    if (request.lines.length === 0) {
      throw new Error('Order must contain at least one line');
    }

    const products = this.productRepository.findAll();

    for (const line of request.lines) {
      if (!products.find(p => p.id === line.productId)) {
        throw new Error(`Product ${line.productId} not found`);
      }
      if (line.quantity <= 0) {
        throw new Error(`Invalid quantity for product ${line.productId}`);
      }
    }

    const orderId = this.generateOrderId();
    const order = new Order(orderId, request.lines);

    if (!this.stockManager.canReserveStock(products, order)) {
      throw new Error('Insufficient stock for one or more products');
    }

    this.stockManager.reserveStock(products, order);
    this.orderRepository.save(order);

    return this.mapToDto(order);
  }

  private generateOrderId(): string {
    return `order-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  private mapToDto(order: Order): OrderDto {
    return {
      id: order.id,
      status: order.getStatus(),
      lines: order.lines,
      createdAt: order.createdAt.toISOString()
    };
  }
}

