import { OrderStatus } from '../../domain/entities/Order';
import { OrderRepository } from '../../domain/repositories/OrderRepository';
import { OrderDto, OrderUpdateRequest } from '../dtos/OrderDto';

export class UpdateOrderStatusUseCase {
  constructor(private orderRepository: OrderRepository) {}

  execute(orderId: string, request: OrderUpdateRequest): OrderDto {
    const order = this.orderRepository.findById(orderId);
    if (!order) {
      throw new Error(`Order ${orderId} not found`);
    }

    const newStatus = request.status as OrderStatus;
    const validStatuses: OrderStatus[] = ['placed', 'paid', 'packed', 'shipped', 'delivered'];

    if (!validStatuses.includes(newStatus)) {
      throw new Error(`Invalid status: ${newStatus}`);
    }

    order.transitionTo(newStatus);

    return {
      id: order.id,
      status: order.getStatus(),
      lines: order.lines,
      createdAt: order.createdAt.toISOString()
    };
  }
}

